'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const read = p => fs.readFileSync(path.resolve(__dirname,'../..',p),'utf8')

const nav = read('ios/UITests/XDriveIOSNavigationRuntimeUITests.swift')
const b9 = read('ios/UITests/XDriveIOSB9ReleaseCrashUITests.swift')
const perf = read('ios/UITests/XDriveIOSPagePerformanceUITests.swift')

test('real first-use Photos interruption can only retry a visible xDrive menu once',()=>{
  const m = nav.slice(nav.indexOf('let sourceCommands:'),nav.indexOf('return false\n    }\n}',nav.indexOf('let sourceCommands:')))
  assert.match(m,/for attempt in 0\.\.<2/)
  assert.match(m,/menu\.exists && menu\.isHittable/)
  assert.match(m,/menuItem\.waitForExistence\(timeout: attempt == 0 \? 8 : 5\)/)
  assert.match(m,/menuItem\.isHittable/)
  assert.match(m,/menuItem\.tap\(\)/)
  assert.match(m,/action\.exists && action\.isHittable/)
  assert.match(m,/action\.tap\(\)/)
  assert.match(m,/action\.isHittable/)
  assert.match(m,/app\.alerts\.firstMatch\.exists/)
  assert.match(m,/bundleIdentifier: "com\.apple\.springboard"/)
  assert.doesNotMatch(m,/simctl|coordinate\(withNormalizedOffset:|launchEnvironment\[/)
})
test('both candidate and archived b9 navigate through actual visible More menu',()=>{
  assert.match(b9,/for attempt in 0\.\.<2/)
  assert.match(b9,/menu\.exists && menu\.isHittable/)
  assert.match(b9,/item\.isHittable/)
  assert.match(b9,/XCTFail\("Actual Gallery More menu missing native route/)
  assert.doesNotMatch(b9,/XDriveIOSNativePhotosTestNavigator\.tap/)
})
test('native page timings use real Gallery and Files route, not hidden SwiftUI tabs',()=>{
  assert.match(perf,/XDriveIOSNativePhotosTestNavigator\.tap\(id, in: app\)/)
  assert.match(perf,/control\.waitForExistence\(timeout: 15\) && control\.isHittable/)
  assert.match(perf,/measure\("tab\.files"/)
  assert.match(perf,/measure\("tab\.gallery"/)
  assert.doesNotMatch(perf,/coordinate\(withNormalizedOffset:|launchEnvironment\[/)
})
